// Canary de API (CloudWatch Synthetics, runtime syn-nodejs-puppeteer-*).
// Verifica que TARGET_URL responda 2xx y lo reporta como métrica SuccessPercent.
const synthetics = require("Synthetics");
const log = require("SyntheticsLogger");

const apiCanary = async function () {
  const url = new URL(process.env.TARGET_URL);

  const requestOptions = {
    hostname: url.hostname,
    method: "GET",
    path: url.pathname,
    port: 443,
    protocol: "https:",
    headers: { "User-Agent": synthetics.getCanaryUserAgentString() },
  };

  const validate = async function (res) {
    return new Promise((resolve, reject) => {
      if (res.statusCode < 200 || res.statusCode > 299) {
        reject(new Error(`${res.statusCode} ${res.statusMessage}`));
      }
      res.on("data", () => {});
      res.on("end", () => resolve());
    });
  };

  synthetics.getConfiguration().setConfig({
    includeRequestHeaders: true,
    includeResponseHeaders: true,
    restrictedHeaders: ["authorization", "x-api-key"],
  });

  log.info(`Verificando ${url.href}`);
  await synthetics.executeHttpStep("health", requestOptions, validate);
};

exports.handler = async () => {
  return await apiCanary();
};
